-- Forward rebuild only; include exact receipt, unassignable dates and settlements.
DROP VIEW closing_fact_basis;
CREATE VIEW closing_fact_basis AS SELECT b.id AS book_id,json_object('books',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'name',t.name,'period',t.period) AS record FROM books t WHERE t.id=b.id ORDER BY t.id,t.firm_id,t.company_id))),'periods',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('book_id',t.book_id,'period',t.period,'status',t.status) AS record FROM periods t WHERE t.book_id=b.id ORDER BY t.book_id,t.period,t.status))),'sources',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'book_id',t.book_id,'external_id',t.external_id,'source_name',t.source_name,'date',t.date,'description',t.description,'counterparty',t.counterparty,'amount_cents',t.amount_cents,'direction',t.direction,'evidence_ref',t.evidence_ref,'fingerprint',t.fingerprint,'source_kind',t.source_kind) AS record FROM sources t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.external_id))),'drafts',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'book_id',t.book_id,'source_id',t.source_id,'description',t.description,'status',t.status,'version',t.version,'explanation',t.explanation,'approved_by',t.approved_by,'approved_at',t.approved_at,'exported_at',t.exported_at,'last_manual_edit_version',t.last_manual_edit_version) AS record FROM drafts t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.source_id))),'draft_lines',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('draft_id',t.draft_id,'book_id',t.book_id,'ordinal',t.ordinal,'account_code',t.account_code,'debit_cents',t.debit_cents,'credit_cents',t.credit_cents) AS record FROM draft_lines t WHERE t.book_id=b.id ORDER BY t.draft_id,t.book_id,t.ordinal))),'draft_line_auxiliaries',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('draft_id',t.draft_id,'book_id',t.book_id,'ordinal',t.ordinal,'values_json',t.values_json) AS record FROM draft_line_auxiliaries t WHERE t.book_id=b.id ORDER BY t.draft_id,t.book_id,t.ordinal))),'accounts',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('book_id',t.book_id,'code',t.code,'name',t.name,'active',t.active,'category',t.category,'normal_balance',t.normal_balance,'auxiliary_requirements',t.auxiliary_requirements,'version',t.version) AS record FROM accounts t WHERE t.book_id=b.id ORDER BY t.book_id,t.code,t.name))),'source_evidence',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'source_id',t.source_id,'book_id',t.book_id,'evidence_ref',t.evidence_ref,'created_at',t.created_at,'created_by',t.created_by) AS record FROM source_evidence t WHERE t.book_id=b.id ORDER BY t.id,t.source_id,t.book_id))),'business_mappings',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('event_id',t.event_id,'firm_id',t.firm_id,'company_id',t.company_id,'book_id',t.book_id,'source_id',t.source_id,'draft_id',t.draft_id,'submitted_version',t.submitted_version,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'created_by',t.created_by,'created_at',t.created_at) AS record FROM business_mappings t WHERE t.book_id=b.id ORDER BY t.event_id,t.firm_id,t.company_id))),'business_mapping_versions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('event_id',t.event_id,'firm_id',t.firm_id,'company_id',t.company_id,'book_id',t.book_id,'source_id',t.source_id,'draft_id',t.draft_id,'submitted_version',t.submitted_version,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'created_by',t.created_by,'created_at',t.created_at) AS record FROM business_mapping_versions t WHERE t.book_id=b.id ORDER BY t.event_id,t.firm_id,t.company_id))),'business_events',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'department_id',t.department_id,'applicant_id',t.applicant_id,'template_id',t.template_id,'template_version',t.template_version,'version',t.version,'status',t.status,'payload',t.payload,'submitted_version',t.submitted_version,'created_at',t.created_at,'updated_at',t.updated_at,'create_key',t.create_key,'creation_fingerprint',t.creation_fingerprint,'fact_version',t.fact_version) AS record FROM business_events t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id AND (substr(json_extract(t.payload,'$.occurred_on'),1,7)=b.period OR (t.status<>'handed_off' AND NOT (COALESCE(length(json_extract(t.payload,'$.occurred_on'))=10 AND json_extract(t.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(t.payload,'$.occurred_on'),'+0 days')=json_extract(t.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions m WHERE m.event_id=t.id AND m.book_id=b.id)) ORDER BY t.id,t.firm_id,t.company_id))),'business_attachments',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'event_id',t.event_id,'firm_id',t.firm_id,'company_id',t.company_id,'storage_key',t.storage_key,'filename',t.filename,'media_type',t.media_type,'sha256',t.sha256,'size_bytes',t.size_bytes,'created_at',t.created_at,'created_by',t.created_by) AS record FROM business_attachments t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.event_id,t.firm_id))),'case_tasks',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'book_id',t.book_id,'source_id',t.source_id,'draft_id',t.draft_id,'kind',t.kind,'title',t.title,'request_reason',t.request_reason,'required_fields',t.required_fields,'attachment_required',t.attachment_required,'recipient_id',t.recipient_id,'assignee_id',t.assignee_id,'priority',t.priority,'due_on',t.due_on,'state',t.state,'version',t.version,'evidence_revision',t.evidence_revision,'accepted_fact_revision',t.accepted_fact_revision,'created_by',t.created_by,'created_at',t.created_at,'updated_at',t.updated_at) AS record FROM case_tasks t WHERE t.book_id=b.id OR t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.firm_id,t.company_id))),'case_responses',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'case_id',t.case_id,'firm_id',t.firm_id,'company_id',t.company_id,'state',t.state,'message',t.message,'fields',t.fields,'created_by',t.created_by,'created_at',t.created_at,'submitted_at',t.submitted_at,'reviewed_by',t.reviewed_by,'reviewed_at',t.reviewed_at,'review_reason',t.review_reason,'supersedes_attachment_ids',t.supersedes_attachment_ids) AS record FROM case_responses t WHERE t.case_id IN(SELECT c.id FROM case_tasks c WHERE c.book_id=b.id OR c.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id)))) ORDER BY t.id,t.case_id,t.firm_id))),'case_supersessions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('old_attachment_id',t.old_attachment_id,'event_id',t.event_id,'case_id',t.case_id,'response_id',t.response_id,'firm_id',t.firm_id,'company_id',t.company_id,'accepted_by',t.accepted_by,'accepted_at',t.accepted_at) AS record FROM case_supersessions t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.old_attachment_id,t.event_id,t.case_id))),'ocr_jobs',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'batch_id',t.batch_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'attachment_id',t.attachment_id,'expected_version',t.expected_version,'attachment_sha256',t.attachment_sha256,'configuration_fingerprint',t.configuration_fingerprint,'execution_user_id',t.execution_user_id,'created_by',t.created_by,'created_