.result_draft_version,'error_code',t.error_code,'error_detail',t.error_detail,'updated_at',t.updated_at,'finished_at',t.finished_at,'result_rule_id',t.result_rule_id,'result_rule_version',t.result_rule_version) AS record FROM proposal_jobs t WHERE t.book_id=b.id ORDER BY t.id,t.firm_id,t.company_id))),'ai_runs',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'kind',t.kind,'attachment_id',t.attachment_id,'draft_id',t.draft_id,'book_id',t.book_id,'input_version',t.input_version,'input_fingerprint',t.input_fingerprint,'idempotency_key',t.idempotency_key,'status',t.status,'result_json',t.result_json,'provider',t.provider,'model',t.model,'prompt_version',t.prompt_version,'usage_json',t.usage_json,'error_code',t.error_code,'error_detail',t.error_detail,'created_by',t.created_by,'created_at',t.created_at,'finished_at',t.finished_at,'cache_hit',t.cache_hit) AS record FROM ai_runs t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.firm_id,t.company_id))),'model_costs',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'run_id',t.run_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'kind',t.kind,'created_by',t.created_by,'period',t.period,'provider',t.provider,'model',t.model,'charge_token',t.charge_token,'pricing_json',t.pricing_json,'quota_enabled',t.quota_enabled,'reserved_micro',t.reserved_micro,'estimated_micro',t.estimated_micro,'confirmed_micro',t.confirmed_micro,'input_tokens',t.input_tokens,'output_tokens',t.output_tokens,'state',t.state,'version',t.version,'created_at',t.created_at,'sent_at',t.sent_at,'finished_at',t.finished_at,'overrun',t.overrun,'manual_reason',t.manual_reason,'manual_by',t.manual_by) AS record FROM model_costs t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.run_id,t.firm_id))),'ai_findings',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'run_id',t.run_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'code',t.code,'severity',t.severity,'payload_json',t.payload_json,'fingerprint',t.fingerprint,'created_at',t.created_at) AS record FROM ai_findings t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.run_id,t.firm_id))),'ai_finding_reviews',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'finding_id',t.finding_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'reason',t.reason,'created_by',t.created_by,'created_at',t.created_at) AS record FROM ai_finding_reviews t WHERE t.event_id IN(SELECT e.id FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND (substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR (e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1)) OR EXISTS(SELECT 1 FROM business_mapping_versions mv WHERE mv.event_id=e.id AND mv.book_id=b.id))) ORDER BY t.id,t.finding_id,t.firm_id))),'ai_bank_links',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('bank_source_id',t.bank_source_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'book_id',t.book_id,'created_by',t.created_by,'created_at',t.created_at) AS record FROM ai_bank_links t WHERE t.book_id=b.id ORDER BY t.bank_source_id,t.firm_id,t.company_id))),'bank_import_keys',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('source_id',t.source_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'namespace',t.namespace,'bank_account',t.bank_account,'stable_transaction_id',t.stable_transaction_id,'original_external_id',t.original_external_id,'content_fingerprint',t.content_fingerprint,'created_by',t.created_by,'created_at',t.created_at) AS record FROM bank_import_keys t WHERE t.book_id=b.id ORDER BY t.source_id,t.book_id,t.firm_id))),'bank_duplicate_decisions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('source_id',t.source_id,'other_source_id',t.other_source_id,'book_id',t.book_id,'firm_id',t.firm_id,'source_fingerprint',t.source_fingerprint,'other_fingerprint',t.other_fingerprint,'expected_draft_version',t.expected_draft_version,'reason',t.reason,'reviewed_by',t.reviewed_by,'created_at',t.created_at) AS record FROM bank_duplicate_decisions t WHERE t.book_id=b.id ORDER BY t.source_id,t.other_source_id,t.book_id))),'bank_source_dispositions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'book_id',t.book_id,'company_id',t.company_id,'source_id',t.source_id,'canonical_source_id',t.canonical_source_id,'source_fingerprint',t.source_fingerprint,'canonical_fingerprint',t.canonical_fingerprint,'expected_version',t.expected_version,'reason',t.reason,'reviewed_by',t.reviewed_by,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'created_at',t.created_at) AS record FROM bank_source_dispositions t WHERE t.book_id=b.id ORDER BY t.id,t.firm_id,t.book_id))),'exports',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'book_id',t.book_id,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'csv',t.csv,'count',t.count,'filename',t.filename,'created_at',t.created_at,'created_by',t.created_by) AS record FROM exports t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.idempotency_key))),'delivery_manifests',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('export_id',t.export_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'period',t.period,'origin',t.origin,'payload_json',t.payload_json,'created_by',t.created_by,'created_at',t.created_at) AS record FROM delivery_manifests t WHERE t.book_id=b.id ORDER BY t.export_id,t.book_id,t.firm_id))),'delivery_receipts',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'export_id',t.export_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'body_json',t.body_json,'request_fingerprint',t.request_fingerprint,'idempotency_key',t.idempotency_key,'reason',t.reason,'import_format',t.import_format,'raw_hash',t.raw_hash,'created_by',t.created_by,'created_at',t.created_at) AS record FROM delivery_receipts t WHERE t.book_id=b.id ORDER BY t.id,t.export_id,t.book_id))),'delivery_receipt_items',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('receipt_id',t.receipt_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'ordinal',t.ordinal,'claimed_draft_id',t.claimed_draft_id,'external_voucher_id',t.external_voucher_id,'raw_json',t.raw_json) AS record FROM delivery_receipt_items t WHERE t.book_id=b.id ORDER BY t.receipt_id,t.book_id,t.firm_id))),'fact_revisions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'old_book_id',t.old_book_id,'old_source_id',t.old_source_id,'old_draft_id',t.old_draft_id,'target_book_id',t.target_book_id,'expected_event_version',t.expected_event_version,'expected_fact_version',t.expected_fact_version,'expected_draft_version',t.expected_draft_version,'old_snapshot',t.old_snapshot,'proposed_payload',t.proposed_payload,'reason',t.reason,'proposed_by',t.proposed_by,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'state',t.state,'version',t.version,'created_at',t.created_at) AS record FROM fact_revisions t WHERE t.old_book_id=b.id OR t.target_book_id=b.id ORDER BY t.id,t.firm_id,t.company_id))),'fact_revision_lineage',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('revision_id',t.revision_id,'firm_id',t.firm_id,'company_id',t.company_id,'event_id',t.event_id,'old_book_id',t.old_book_id,'old_source_id',t.old_source_id,'old_draft_id',t.old_draft_id,'new_book_id',t.new_book_id,'new_source_id',t.new_source_id,'new_draft_id',t.new_draft_id,'old_fact_version',t.old_fact_version,'new_fact_version',t.new_fact_version,'created_at',t.created_at) AS record FROM fact_revision_lineage t WHERE t.old_book_id=b.id OR t.new_book_id=b.id ORDER BY t.revision_id,t.firm_id,t.company_id))),'company_master_entities',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'kind',t.kind,'code',t.code,'name',t.name,'active',t.active,'version',t.version,'recorded_book_id',t.recorded_book_id,'created_by',t.created_by,'created_at',t.created_at) AS record FROM company_master_entities t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id ORDER BY t.id,t.firm_id,t.company_id))),'company_master_aliases',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'kind',t.kind,'entity_id',t.entity_id,'original',t.original,'reason',t.reason,'status',t.status,'version',t.version,'recorded_book_id',t.recorded_book_id,'created_by',t.created_by,'created_at',t.created_at,'reviewed_by',t.reviewed_by,'review_reason',t.review_reason,'reviewed_at',t.reviewed_at) AS record FROM company_master_aliases t WHERE t.firm_id=b.firm_id AND t.company_id=b.company_id ORDER BY t.id,t.firm_id,t.company_id))),'journal_templates',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'book_id',t.book_id,'active',t.active,'current_version',t.current_version,'created_by',t.created_by,'created_at',t.created_at) AS record FROM journal_templates t WHERE t.book_id=b.id ORDER BY t.id,t.book_id,t.active))),'journal_template_versions',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('template_id',t.template_id,'book_id',t.book_id,'version',t.version,'definition',t.definition,'definition_fingerprint',t.definition_fingerprint,'created_by',t.created_by,'created_at',t.created_at) AS record FROM journal_template_versions t WHERE t.book_id=b.id ORDER BY t.template_id,t.book_id,t.version))),'learning_rules',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'book_id',t.book_id,'period',t.period,'current_version',t.current_version,'state_version',t.state_version,'status',t.status,'evaluation_id',t.evaluation_id,'created_by',t.created_by,'created_at',t.created_at,'updated_at',t.updated_at) AS record FROM learning_rules t WHERE t.book_id=b.id ORDER BY t.id,t.firm_id,t.company_id))),'settlement_items',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'firm_id',t.firm_id,'company_id',t.company_id,'book_id',t.book_id,'source_id',t.source_id,'event_id',t.event_id,'fact_version',t.fact_version,'source_fingerprint',t.source_fingerprint,'counterparty_id',t.counterparty_id,'counterparty_kind',t.counterparty_kind,'counterparty_original',t.counterparty_original,'amount_cents',t.amount_cents,'direction',t.direction,'clearing_account',t.clearing_account,'created_by',t.created_by,'created_at',t.created_at,'idempotency_key',t.idempotency_key,'request_fingerprint',t.request_fingerprint,'reason',t.reason) AS record FROM settlement_items t WHERE t.book_id=b.id ORDER BY t.id,t.firm_id,t.company_id))),'settlement_allocations',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'command_id',t.command_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'item_id',t.item_id,'bank_source_id',t.bank_source_id,'amount_cents',t.amount_cents,'clearing_account',t.clearing_account,'created_by',t.created_by,'created_at',t.created_at) AS record FROM settlement_allocations t WHERE t.book_id=b.id ORDER BY t.id,t.command_id,t.book_id))),'settlement_reversals',json((SELECT COALESCE(json_group_array(json(record)),'[]') FROM (SELECT json_object('id',t.id,'allocation_id',t.allocation_id,'book_id',t.book_id,'firm_id',t.firm_id,'company_id',t.company_id,'created_by',t.created_by,'created_at',t.created_at,'idempotency_key',t.idempotency_key,'reason',t.reason,'expected_fingerprint',t.expected_fingerprint) AS record FROM settlement_reversals t WHERE t.book_id=b.id ORDER BY t.id,t.allocation_id,t.book_id)))) AS inputs_json FROM books b;
DROP VIEW closing_issue_rows;
CREATE VIEW closing_issue_rows AS WITH book AS (SELECT * FROM books),
      active_sources AS (SELECT s.* FROM sources s JOIN book b ON b.id=s.book_id WHERE NOT EXISTS(SELECT 1 FROM bank_source_dispositions z WHERE z.book_id=s.book_id AND z.source_id=s.id) AND NOT EXISTS(SELECT 1 FROM fact_revision_lineage z WHERE z.old_book_id=s.book_id AND z.old_source_id=s.id)),
      active_drafts AS (SELECT d.* FROM drafts d JOIN active_sources s ON s.id=d.source_id AND s.book_id=d.book_id
        WHERE NOT EXISTS(SELECT 1 FROM ai_bank_links link WHERE link.bank_source_id=s.id AND link.book_id=s.book_id)),
      event_scope AS (SELECT e.*,b.id AS scope_book_id FROM business_events e JOIN book b ON b.firm_id=e.firm_id AND b.company_id=e.company_id
        WHERE substr(json_extract(e.payload,'$.occurred_on'),1,7)=b.period OR EXISTS(SELECT 1 FROM business_mappings m WHERE m.event_id=e.id AND m.book_id=b.id)),
      issues AS (
      SELECT d.book_id AS book_id,'unreviewed' AS category,'draft' AS object_type,d.id AS object_id,'尚有未审核或未导出的有效凭证' AS detail FROM active_drafts d WHERE d.status<>'exported'
      UNION ALL SELECT s.book_id,'unprocessed','source',s.id,'来源尚未形成有效凭证草稿' FROM active_sources s WHERE NOT EXISTS(SELECT 1 FROM drafts d WHERE d.book_id=s.book_id AND d.source_id=s.id)
      UNION ALL SELECT s.book_id,'missing_evidence','source',s.id,'当前有效来源缺少原件或证据引用' FROM active_sources s WHERE trim(COALESCE((SELECT se.evidence_ref FROM source_evidence se WHERE se.book_id=s.book_id AND se.source_id=s.id ORDER BY se.id DESC LIMIT 1),s.evidence_ref))=''
      UNION ALL SELECT b.id,'business_pending','book',b.id,'本企业本期仍有未完成审批或移交的业务事项，请企业财务核对' FROM book b WHERE EXISTS(SELECT 1 FROM event_scope e WHERE e.scope_book_id=b.id AND e.status<>'handed_off')
      UNION ALL SELECT b.id,'missing_evidence','book',b.id,'本企业仍有发生日期缺失或无效的未移交资料，无法确定归期，请企业财务修正' FROM book b WHERE EXISTS(SELECT 1 FROM business_events e WHERE e.firm_id=b.firm_id AND e.company_id=b.company_id AND e.status<>'handed_off' AND NOT (COALESCE(length(json_extract(e.payload,'$.occurred_on'))=10 AND json_extract(e.payload,'$.occurred_on') GLOB '20[0-9][0-9]-[0-1][0-9]-[0-3][0-9]' AND strftime('%Y-%m-%d',json_extract(e.payload,'$.occurred_on'),'+0 days')=json_extract(e.payload,'$.occurred_on'),0)=1))
      UNION ALL SELECT m.book_id,'missing_evidence','event',m.event_id,'已移交事项缺少当前有效附件' FROM business_mappings m JOIN book b ON b.id=m.book_id
        WHERE NOT EXISTS(SELECT 1 FROM business_attachments a WHERE a.event_id=m.event_id AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=a.event_id AND z.old_attachment_id=a.id))
      UNION ALL SELECT b.id,'open_cases','case',c.id,'本账套仍有未关闭的异常或补件待办' FROM case_tasks c JOIN book b ON c.book_id=b.id OR c.event_id IN(SELECT m.event_id FROM business_mappings m WHERE m.book_id=b.id) WHERE c.state<>'closed'
      UNION ALL SELECT b.id,'open_cases','book',b.id,'本企业本期未移交事项仍有待处理补件，请企业财务核对' FROM book b WHERE EXISTS(SELECT 1 FROM case_tasks c JOIN event_scope e ON e.id=c.event_id AND e.scope_book_id=b.id WHERE c.book_id IS NULL AND c.state<>'closed' AND NOT EXISTS(SELECT 1 FROM business_mappings m WHERE m.event_id=e.id AND m.book_id=b.id))
      UNION ALL SELECT m_book.book_id,'background_pending','ocr_job',q.id,'票据识别仍在运行或存在发送结果未知的任务' FROM ocr_jobs q JOIN event_scope e ON e.id=q.event_id JOIN business_mappings m_book ON m_book.event_id=e.id AND m_book.book_id=e.scope_book_id WHERE q.status IN ('queued','running','retry_wait') AND NOT EXISTS(SELECT 1 FROM case_supersessions z WHERE z.event_id=q.event_id AND z.old_attachment_id=q.attachment_id) AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT q.book_id,'background_pending','proposal_job',q.id,'分录任务仍在运行或等待人工处理' FROM proposal_jobs q JOIN book b ON b.id=q.book_id WHERE q.status IN ('waiting','queued','running','retry_wait') OR q.status IN ('needs_attention','interrupted','failed') AND EXISTS(SELECT 1 FROM drafts d WHERE d.id=q.draft_id AND d.book_id=q.book_id AND d.status='draft')
      UNION ALL SELECT m_book.book_id,'background_pending','event',r.event_id,'仍有未完成的模型执行记录' FROM ai_runs r JOIN event_scope e ON e.id=r.event_id JOIN business_mappings m_book ON m_book.event_id=e.id AND m_book.book_id=e.scope_book_id WHERE r.status='running' AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT m_book.book_id,'model_uncertain','event',c.event_id,'仍有模型外发结果或费用未知的记录' FROM model_costs c JOIN event_scope e ON e.id=c.event_id JOIN business_mappings m_book ON m_book.event_id=e.id AND m_book.book_id=e.scope_book_id WHERE c.state='uncertain' AND EXISTS(SELECT 1 FROM business_mappings m JOIN book b ON b.id=m.book_id WHERE m.event_id=e.id)
      UNION ALL SELECT s.book_id,'unmatched_bank','source',s.id,'银行来源未匹配业务事项，也未形成独立已导出的凭证' FROM active_sources s WHERE s.source_kind='bank' AND NOT EXISTS(SELECT 1 FROM ai_bank_links l WHERE l.bank_source_id=s.id AND l.book_id=s.book_id) AND NOT EXISTS(SELECT 1 FROM drafts d WHERE d.source_id=s.id AND d.book_id=s.book_id AND d.status='exported')
      UNION ALL SELECT s.book_id,'unmatched_bank','source',s.id,'银行收付核销尚未分配完整金额，待清偿事项仍须核对' FROM active_sources s WHERE s.source_kind='bank'
        AND EXISTS(SELECT 1 FROM settlement_allocations a WHERE a.book_id=s.book_id AND a.bank_source_id=s.id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id AND r.book_id=a.book_id))
        AND (SELECT COALESCE(sum(a.amount_cents),0) FROM settlement_allocations a WHERE a.book_id=s.book_id AND a.bank_source_id=s.id AND NOT EXISTS(SELECT 1 FROM settlement_reversals r WHERE r.allocation_id=a.id AND r.book_id=a.book_id))<>s.amount_cents
      UNION ALL SELECT m.book_id,'unmatched_business','event',m.event_id,'已支付业务事项尚未匹配银行来源，请先核对防止重复记账' FROM business_mappings m JOIN event_scope e ON e.id=m.event_id AND e.scope_book_id=m.book_id JOIN book b ON b.id=m.book_id
        WHERE json_extract(e.payload,'$.payment_status')='paid' AND NOT EXISTS(SELECT 1 FROM ai_bank_links l WHERE l.event_id=m.event_id AND l.book_id=m.book_id)
        AND NOT EXISTS(SELECT 1 FROM fact_revision_lineage z WHERE z.old_book_id=m.book_id AND z.old_source_id=m.source_id)
      UNION ALL SELECT x.book_id,'delivery_pending','export',x.id,'导出后缺少内容一致的完整导入回执，或回执仍有未知及差异' FROM exports x JOIN book b ON b.id=x.book_id WHERE NOT EXISTS(SELECT 1 FROM delivery_manifests m JOIN delivery_receipts r ON r.export_id=m.export_id AND r.book_id=m.book_id
      WHERE m.export_id=x.id AND m.book_id=x.book_id AND json_extract(r.body_json,'$.book_id')=json_extract(m.payload_json,'$.book_id') AND json_extract(r.body_json,'$.company_id')=json_extract(m.payload_json,'$.company_id') AND json_extract(r.body_json,'$.period')=json_extract(m.payload_json,'$.period') AND json_extract(r.body_json,'$.currency')=json_extract(m.payload_json,'$.currency')
      AND NOT EXISTS(SELECT 1 FROM delivery_receipts newer WHERE newer.export_id=r.export_id AND newer.book_id=r.book_id AND (newer.created_at>r.created_at OR newer.created_at=r.created_at AND newer.id>r.id))
      AND (SELECT count(*) FROM json_each(r.body_json,'$.items') i)=(SELECT count(*) FROM json_each(m.payload_json,'$.items') expected)
      AND (SELECT count(*) FROM json_each(r.body_json,'$.items') i)=x.count
      AND NOT EXISTS(SELECT 1 FROM json_each(r.body_json,'$.items') i
        WHERE json_extract(i.value,'$.status') IS NULL OR json_extract(i.value,'$.status')<>'accepted' OR trim(COALESCE(json_extract(i.value,'$.external_voucher_id'),''))=''
        OR (SELECT count(*) FROM json_each(r.body_json,'$.items') duplicate WHERE json_extract(duplicate.value,'$.draft_id')=json_extract(i.value,'$.draft_id'))<>1
        OR (SELECT count(*) FROM json_each(r.body_json,'$.items') duplicate WHERE json_extract(duplicate.value,'$.external_voucher_id')=json_extract(i.value,'$.external_voucher_id'))<>1
        OR EXISTS(SELECT 1 FROM delivery_receipt_items h WHERE h.book_id=r.book_id AND h.receipt_id<>r.id AND
          (h.claimed_draft_id<>json_extract(i.value,'$.draft_id') AND h.external_voucher_id=json_extract(i.value,'$.external_voucher_id')
           OR h.claimed_draft_id=json_extract(i.value,'$.draft_id') AND trim(COALESCE(h.external_voucher_id,''))<>'' AND h.external_voucher_id<>json_extract(i.value,'$.external_voucher_id')))
        OR NOT EXISTS(SELECT 1 FROM json_each(m.payload_json,'$.items') expected WHERE json_extract(expected.value,'$.draft_id')=json_extract(i.value,'$.draft_id') AND (json_extract(i.value,'$.date')) IS (json_extract(expected.value,'$.date')) AND (json_extract(i.value,'$.amount')) IS (json_extract(expected.value,'$.amount')) AND (json_extract(i.value,'$.description')) IS (json_extract(expected.value,'$.description'))
          AND (SELECT count(*) FROM json_each(i.value,'$.lines') line)=(SELECT count(*) FROM json_each(expected.value,'$.lines') wanted)
          AND (SELECT count(*) FROM json_each(i.value,'$.lines') line)>=2
          AND NOT EXISTS(SELECT 1 FROM json_each(i.value,'$.lines') line WHERE NOT EXISTS(SELECT 1 FROM json_each(expected.value,'$.lines') wanted
            WHERE (json_extract(line.value,'$.ordinal')) IS (json_extract(wanted.value,'$.ordinal')) AND (json_extract(line.value,'$.account_code')) IS (json_extract(wanted.value,'$.account_code')) AND (json_extract(line.value,'$.debit')) IS (json_extract(wanted.value,'$.debit')) AND (json_extract(line.value,'$.credit')) IS (json_extract(wanted.value,'$.credit')) AND json_type(line.value,'$.auxiliary_values')='object' AND (json_extract(line.value,'$.auxiliary_values.department')) IS (json_extract(wanted.value,'$.auxiliary_values.department')) AND (json_extract(line.value,'$.auxiliary_values.employee')) IS (json_extract(wanted.value,'$.auxiliary_values.employee')) AND (json_extract(line.value,'$.auxiliary_values.counterparty')) IS (json_extract(wanted.value,'$.auxiliary_values.counterparty')) AND (json_extract(line.value,'$.auxiliary_values.project')) IS (json_extract(wanted.value,'$.auxiliary_values.project')) AND (SELECT count(*) FROM json_each(line.value,'$.auxiliary_values'))=(SELECT count(*) FROM json_each(wanted.value,'$.auxiliary_values')))
            OR (SELECT count(*) FROM json_each(i.value,'$.lines') duplicate_line WHERE json_extract(duplicate_line.value,'$.ordinal')=json_extract(line.value,'$.ordinal'))<>1)))
    )
      UNION ALL SELECT b.id,'fact_revision','revision',r.id,'业务事实修订或已导出调整建议尚未完成独立处置' FROM fact_revisions r JOIN book b ON r.old_book_id=b.id OR r.target_book_id=b.id WHERE r.state IN ('pending','adjustment_proposed')
      ) SELECT issues.book_id,issues.category,issues.object_type,issues.object_id,issues.detail FROM issues ORDER BY issues.category,issues.object_type,issues.object_id;
